b=s.index("export const PostPayloadSchema")
s=s[:a]+"""export function parseTagNames(value: string | undefined): string[] {
  return [...new Set((value ?? '').split(',').map((name) => name.trim()).filter((name) => name !== ''))]
}

const TagListSchema = z.string().optional().superRefine((value, ctx) => {
  const names = parseTagNames(value)
  if (names.some((name) => name.length > 30)) {
    ctx.addIssue({ code: 'custom', message: 'Each tag must be 30 characters or fewer.' })
  } else if (names.length > 5) {
    ctx.addIssue({ code: 'custom', message: 'A post may have at most 5 tags.' })
  }
})

"""+s[b:]
